package android.content.res;
import java.io.*;
public class AssetManager {private final File atom,seed;private final long start,length;public AssetManager(File atom,File seed,long start,long length){this.atom=atom;this.seed=seed;this.start=start;this.length=length;}public InputStream open(String name)throws IOException{if(name.equals("research/cp4_molecule_seeds.jsonl"))return new FileInputStream(seed);if(name.equals("cp4_atom_registry.jsonl"))return new FileInputStream(atom);throw new FileNotFoundException(name);}public AssetFileDescriptor openFd(String name)throws IOException{if(name.equals("research/cp4_molecule_seeds.jsonl"))return new AssetFileDescriptor(seed,0,seed.length());if(!name.equals("cp4_atom_registry.jsonl"))throw new FileNotFoundException(name);return new AssetFileDescriptor(atom,start,length);}}
